];
function renderVoices() {
  const root = document.getElementById(\"voices\");
  for (const v of VOICES) {
    const g = el(\"div\", {class: \"vgroup\"}, el(\"b\", {text: v.title}));
    for (const [set, desc] of v.sets) for (const n of [1, 2, 3]) {
