91	void AJamGameMode::ReadFightKeys(UJamFightSubsystem& Host, const AJamPlayerController& Player)
92	{
93	#if !UE_BUILD_SHIPPING
94		if (Player.WasInputKeyJustPressed(EKeys::F5))
95		{
96			Host.DebugSkip();
97		}
98		if (Player.WasInputKeyJustPressed(EKeys::F6))
99		{
100			Host.Restart();
101		}
102	#endif
103		// R answers an ending only: a slip of the finger in the middle of the fight costs nothing.
104		const EJamPhase Phase = Host.GetFight().Phase;
105		if (Player.WasInputKeyJustPressed(EKeys::R) || Player.WasInputKeyJustPressed(EKeys::Enter))
106		{
107			if (Phase == EJamPhase::HeroDead)
108			{
109				Host.Retry();
110			}
111			else if (Phase == EJamPhase::Won)
112			{
113				Host.Restart();
114			}
115		}
116	}
