123	void AJamGameMode::ApplyLayers(const FJamFight& Fight, float Time)
124	{
125		AJamHUD* Hud = Cast<AJamHUD>(GetWorld()->GetFirstPlayerController()->GetHUD());
126		const FJamLayers Wanted = JamLayerRules::For(Fight.Steal.Done, Fight.Phase, LayerSettings);
127		if (!(Wanted == ShownLayers) && CrackStart < 0.f)
128		{
129			if (!bCrackPending)
130			{
131				// This frame still shows the old look: it is the picture the crack opens through.
132				bCrackPending = true;
133				if (Hud)
134				{
135					Hud->CrackFrame = Rig->Freeze();
136				}
137			}
138			else
139			{
140				bCrackPending = false;
141				ShownLayers = Wanted;
142				CrackStart = Time;
143				++CrackSeed;
144			}
145		}
146		if (CrackStart >= 0.f && JamCrackRules::IsOver(Time - CrackStart, JamCrackRules::Seconds))
147		{
148			CrackStart = -1.f;
149		}
150		if (Hud)
151		{
152			Hud->CrackAge = CrackStart >= 0.f ? Time - CrackStart : -1.f;
153			Hud->CrackSeed = CrackSeed;
154		}
155		const FJamLayers& Left = ShownLayers;
156		HeroView->SetLayers(Left);
157		Arena->SetMaterials(Left.bMaterials);
158		Effects->bHeroEffects = Left.bEffects;
159		Effects->bArt = Left.bArt;
160		Rig->SetBloom(JamNeonRules::Bloom(Left, Neon));
161		// T-077: Lumen, the neon lights and the grade go with the full art, the rest of the post with the effects.
162		const EJamLight Light = JamNeonRules::LightFor(Left);
163		Rig->SetLight(Light);
164		Lights->SetLight(Light);
165		Music->SetStems(JamLayerRules::StemsFor(Fight.Steal.Done, Fight.Phase, LayerSettings));
166		// T-072: the full Ultimate's cue and the dash degrade with the look.
167		Effects->ChargeLook = JamFxRules::ChargeLook(Left);
168		if (Hud)
169		{
170			Hud->bBars = Left.bHud;
171		}
172	}
