174	void AJamGameMode::SyncViews(const UJamFightSubsystem& Host, float Time)
175	{
176		const FJamFight& Fight = Host.GetFight();
177		const float Alpha = Host.GetAlpha();
178		ApplyLayers(Fight, Time);
179		for (const FJamEvent& Event : Host.GetFrameEvents())
180		{
181			if (Event.Type == EJamEvent::Hit)
182			{
183				(Event.Side == EJamSide::Hero ? HeroView : BossView)
184					->Flash(Time, JamFeedbackRules::FlashWeight(Event.Side, Event.Amount, Feedback));
185			}
186			Rig->Kick(JamFeedbackRules::ShakeKick(Event, Feedback), Time);
187		}
188		JamTeachRules::Learn(Lessons, Host.GetFrameEvents());
189		const int32 ParryCue = JamTeachRules::ParryPromptFor(Fight, Lessons, Teach);
190		const EJamUltimateCall UltimateCall = JamTeachRules::UltimateCallFor(Fight, Lessons);
191		Effects->ParryCue = ParryCue;
192		Effects->bUltimateReady = UltimateCall != EJamUltimateCall::None;
193		if (AJamHUD* Hud = Cast<AJamHUD>(GetWorld()->GetFirstPlayerController()->GetHUD()))
194		{
195			Hud->bParryPrompt = ParryCue != INDEX_NONE;
196			Hud->UltimateCall = UltimateCall;
197		}
198		HeroView->Act(Fight, Host.GetFrameEvents(), Time);
199		BossView->Act(Fight, Host.GetFrameEvents(), Time);
200		HeroView->Sync(Fight.Fighters[EJamSide::Hero], Alpha, Time);
201		BossView->Sync(Fight.Fighters[EJamSide::Boss], Alpha, Time);
202		Arena->Pulse(JamNeonRules::LineGlow(GetWorld()->GetRealTimeSeconds() - MusicStart, Neon));
203		Projectiles->Hands[EJamSide::Hero] = HeroView->ThrowingHand();
204		Projectiles->Hands[EJamSide::Boss] = BossView->ThrowingHand();
205		Projectiles->bArt = ShownLayers.bArt;
206		Projectiles->Sync(Fight.Projectiles, Alpha, Time);
207		Effects->Sync(Fight, Host.GetFrameEvents(), Alpha, Time);
208		Fx->Sync(Fight, Host.GetFrameEvents(), ShownLayers.bArt, HeroView->GetActorLocation());
209		Money->Sync(Fight, Host.GetFrameEvents(), Time);
210		Sounds->Play(Host.GetFrameEvents(), Fight);
211		Rig->Sync(HeroView->GetActorLocation(), Time);
212		if (Demo.IsClose())
213		{
214			// T-078: a camera closer and lower than the game's, behind the hero, so the steps of his feet read.
215			const FVector Feet = HeroView->GetActorLocation();
216			Rig->Frame(Feet + FVector(-650.0, 0.0, 620.0), Feet + FVector(0.0, 0.0, 60.0), 50.f);
217		}
218	}
