220	void AJamGameMode::Tick(float DeltaSeconds)
221	{
222		Super::Tick(DeltaSeconds);
223		UJamFightSubsystem* Host = GetWorld()->GetSubsystem<UJamFightSubsystem>();
224		AJamPlayerController* Player = Cast<AJamPlayerController>(GetWorld()->GetFirstPlayerController());
225		if (!Host || !Player || !Rig)
226		{
227			return;
228		}
229		const FJamFighter& Hero = Host->GetFight().Fighters[EJamSide::Hero];
230		if (!bPlayerReady)
231		{
232			// The controller ticks first, so the keys read here are this frame's keys.
233			AddTickPrerequisiteActor(Player);
234			Player->SetViewTarget(Rig);
235			Player->UseCursor();
236			bPlayerReady = true;
237			bIntroDone = Demo.SkipsIntro();
238		}
239	
240		const float Time = GetWorld()->GetTimeSeconds();
241		if (Demo.IsGallery() || Demo.IsStrideGallery())
242		{
243			Demo.IsGallery() ? RunGallery(*Host, Time) : RunStrideGallery(*Host, Time);
244			Demo.EndFrame(Time);
245			return;
246		}
247		if (!bIntroDone && RunIntro(*Host, *Player, Time))
248		{
249			Demo.EndFrame(Time);
250			return;
251		}
252		if (Demo.IsOn())
253		{
254			Host->HeroIntent = Demo.Drive(*Host, Time);
255		}
256		else
257		{
258			ReadFightKeys(*Host, *Player);
259			Host->HeroIntent = Player->ReadIntent(*Rig, Hero);
260		}
261		// The fight holds while the crack opens between two looks (T-068).
262		if (!IsCracking(Time))
263		{
264			Host->Advance(DeltaSeconds);
265		}
266		const FJamFight& Now = Host->GetFight();
267		// Only the hero's own wind-up slows the world: the Publisher's long one (T-038) is there to be walked out of.
268		const bool bWindingUp = Now.Fighters[EJamSide::Hero].Ultimate.bPending;
269		UGameplayStatics::SetGlobalTimeDilation(this, bWindingUp ? UltimateTimeDilation : 1.f);
270		SyncViews(*Host, Time);
271		if (!Demo.IsOn())
272		{
273			// The model turns to the cursor on every frame, not on the 60 Hz step: the aim never trails the mouse.
274			const FVector2D Point = Player->LiveAimPoint(Rig->GetActorLocation());
275			const FVector2D Shown(HeroView->GetActorLocation());
276			HeroView->Face(JamAimRules::FacingTo(Point, Shown, Now.Fighters[EJamSide::Hero].Facing));
277		}
278		Demo.EndFrame(Time);
279	}
