281	bool AJamGameMode::RunIntro(const UJamFightSubsystem& Host, const AJamPlayerController& Player, float Time)
282	{
283		AJamHUD* Hud = Cast<AJamHUD>(Player.GetHUD());
284		if (IntroStart < 0.f)
285		{
286			IntroStart = Time;
287			IntroLength = BossView->LengthOf(EJamClip::Entrance);
288			BossView->Perform(EJamClip::Entrance, Time);
289		}
290		const float Age = Time - IntroStart;
291		const bool bSkip = Player.WasInputKeyJustPressed(EKeys::LeftMouseButton) || Player.WasInputKeyJustPressed(EKeys::SpaceBar) ||
292			Player.WasInputKeyJustPressed(EKeys::Enter) || Player.WasInputKeyJustPressed(EKeys::Escape);
293		if (IntroLength <= 0.f || JamIntroRules::IsOver(Age, IntroLength, bSkip, IntroSkipAfter))
294		{
295			bIntroDone = true;
296			BossView->Interrupt(Time);
297			if (Hud)
298			{
299				Hud->IntroAlpha = 0.f;
300			}
301			return false;
302		}
303		if (Hud)
304		{
305			Hud->IntroAlpha = JamIntroRules::TitleAlpha(Age, IntroLength, IntroTitleFade);
306		}
307		// The simulation is not advanced: the fight waits for the show to end.
308		SyncViews(Host, Time);
309		const float ToHero = JamIntroRules::CameraToHero(Age, IntroLength, IntroReturn);
310		Rig->Sync(FMath::Lerp(BossView->GetActorLocation(), HeroView->GetActorLocation(), ToHero), Time);
311		return true;
312	}
