314	void AJamGameMode::RunStrideGallery(const UJamFightSubsystem& Host, float Time)
315	{
316		// Move angles off the facing, to the right positive: ahead, the diagonals, the strafes, the backpedal.
317		static const float Angles[] = { 0.f, 45.f, 90.f, 135.f, 180.f, -135.f, -90.f, -45.f };
318		constexpr float EachSeconds = 1.5f;
319		if (StrideGalleryStart < 0.f)
320		{
321			StrideGalleryStart = Time;
322		}
323		const float Age = Time - StrideGalleryStart;
324		if (Age >= EachSeconds * UE_ARRAY_COUNT(Angles))
325		{
326			const float CircleDt = FMath::Clamp(Time - StrideGalleryTime, 0.f, 0.1f);
327			StrideGalleryTime = Time;
328			RunStrideCircle(Host, Time, Age - EachSeconds * UE_ARRAY_COUNT(Angles), CircleDt);
329			return;
330		}
331		const int32 Index = FMath::Min(FMath::FloorToInt32(Age / EachSeconds), static_cast<int32>(UE_ARRAY_COUNT(Angles)) - 1);
332		FJamFighter Hero = Host.GetFight().Fighters[EJamSide::Hero];
333		const float Dt = StrideGalleryTime < 0.f ? 0.f : FMath::Clamp(Time - StrideGalleryTime, 0.f, 0.1f);
334		// Each way starts again from the hero's own place, so the run stays inside the arena.
335		if (StrideGalleryTime < 0.f || Index != GalleryPose)
336		{
337			StrideGalleryPos = Hero.Pos -
338				FVector2D(FMath::Cos(FMath::DegreesToRadians(Angles[Index])), FMath::Sin(FMath::DegreesToRadians(Angles[Index]))) * 400.0;
339			GalleryPose = Index;
340		}
341		StrideGalleryTime = Time;
342		const float Radians = FMath::DegreesToRadians(Angles[Index]);
343		const FVector2D Dir(FMath::Cos(Radians), FMath::Sin(Radians));
344		Hero.Facing = FVector2D(1.0, 0.0);
345		Hero.PrevPos = StrideGalleryPos;
346		StrideGalleryPos += Dir * Hero.Speed * Dt;
347		Hero.Pos = Hero.PrevPos + Dir * Hero.Speed / JamSim::StepsPerSecond;
348		HeroView->Sync(Hero, 0.f, Time);
349		UE_LOG(LogJamGame, Verbose, TEXT("Stride trace %.0f %.3f %s"), Angles[Index], Age, *HeroView->DescribeStride());
350		if (FMath::Frac(Age / EachSeconds) < 0.02f)
351		{
352			UE_LOG(LogJamGame, Display, TEXT("Stride gallery: moving %.0f degrees off the facing"), Angles[Index]);
353		}
354		// The camera in front of the hero (or above him with -JamStrideTop): the chest faces it, the feet step sideways.
355		const FVector Feet = HeroView->GetActorLocation();
356		Rig->Frame(
357			Feet + (FParse::Param(FCommandLine::Get(), TEXT("JamStrideTop")) ? FVector(-60.0, -60.0, 560.0) : FVector(420.0, -70.0, 190.0)),
358			Feet + FVector(0.0, 0.0, 85.0), 50.f);
359	}
360	
361	void AJamGameMode::RunStrideCircle(const UJamFightSubsystem& Host, float Time, float Age, float Dt)
362	{
363		constexpr float CircleSeconds = 7.f;
364		constexpr float BackSeconds = 1.2f;
365		constexpr float InSeconds = 1.2f;
366		constexpr double Radius = 380.0;
367		const FJamFight& Fight = Host.GetFight();
368		FJamFighter Hero = Fight.Fighters[EJamSide::Hero];
369		FJamFighter Boss = Fight.Fighters[EJamSide::Boss];
370		if (Age < CircleSeconds + BackSeconds + InSeconds)
371		{
372			// The hero circles the Publisher, then backs straight off, then runs back in; he faces him all along.
373			if (StrideCircleAngle > 1.0e9)
374			{
375				StrideCircleAngle = 0.0;
376				StrideCircleRadius = Radius;
377			}
378			const bool bCircling = Age < CircleSeconds;
379			const bool bBacking = !bCircling && Age < CircleSeconds + BackSeconds;
380			const double Step = Hero.Speed * Dt;
381			StrideCircleAngle += bCircling ? Step / StrideCircleRadius : 0.0;
382			StrideCircleRadius += bBacking ? Step : (bCircling ? 0.0 : -Step);
383			const FVector2D Out(FMath::Cos(StrideCircleAngle), FMath::Sin(StrideCircleAngle));
384			const FVector2D Tangent(-Out.Y, Out.X);
385			const FVector2D Move = bCircling ? Tangent : (bBacking ? Out : -Out);
386			Hero.PrevPos = Boss.Pos + Out * StrideCircleRadius;
387			Hero.Pos = Hero.PrevPos + Move * Hero.Speed / JamSim::StepsPerSecond;
388			Hero.Facing = -Out;
389			Boss.PrevPos = Boss.Pos;
390			HeroView->Sync(Hero, 0.f, Time);
391			BossView->Sync(Boss, 0.f, Time);
392			const FVector Between = 0.5 * (HeroView->GetActorLocation() + BossView->GetActorLocation());
393			Rig->Frame(Between + FVector(-850.0, 0.0, 800.0), Between + FVector(0.0, 0.0, 80.0), 50.f);
394			return;
395		}
396		// The Publisher walks east at his own speed, the hero stands by.
397		const float Walked = Age - (CircleSeconds + BackSeconds + InSeconds);
398		Boss.PrevPos = Boss.Pos + FVector2D(Boss.Speed * Walked - 600.0, 0.0);
399		Boss.Pos = Boss.PrevPos + FVector2D(Boss.Speed / JamSim::StepsPerSecond, 0.0);
400		Boss.Facing = FVector2D(1.0, 0.0);
401		Hero.PrevPos = Hero.Pos;
402		HeroView->Sync(Hero, 0.f, Time);
403		BossView->Sync(Boss, 0.f, Time);
404		const FVector Feet = BossView->GetActorLocation();
405		Rig->Frame(Feet + FVector(150.0, -620.0, 260.0), Feet + FVector(0.0, 0.0, 110.0), 50.f);
406	}
407	
408	void AJamGameMode::RunGallery(const UJamFightSubsystem& Host, float Time)
409	{
410		struct FGalleryPose
411		{
412			EJamClip Clip;
413			float ClipTime;
414		};
415		// Every pose the katana and the hands have to look right in: idle, run, both strikes, the guard, the throw, a hit.
416		static const FGalleryPose Poses[] = {
417			{ EJamClip::Idle, 0.5f },
418			{ EJamClip::Idle, 2.5f },
419			{ EJamClip::Move, 0.1f },
420			{ EJamClip::Move, 0.4f },
421			{ EJamClip::StrikeA, 0.35f },
422			{ EJamClip::StrikeA, 0.5f },
423			{ EJamClip::StrikeB, 0.73f },
424			{ EJamClip::Parry, 0.3f },
425			{ EJamClip::Throw, 0.4f },
426			{ EJamClip::Throw, 0.57f },
427			{ EJamClip::Hit, 0.33f },
428			{ EJamClip::Move, 0.25f },
429		};
430		constexpr float PoseSeconds = 0.5f;
431		const int32 Index = FMath::Min(FMath::FloorToInt32(Time / PoseSeconds), static_cast<int32>(UE_ARRAY_COUNT(Poses)) - 1);
432		if (Index != GalleryPose)
433		{
434			GalleryPose = Index;
435			HeroView->HoldPose(Poses[Index].Clip, Poses[Index].ClipTime, Time);
436		}
437		SyncViews(Host, Time);
438		if (FMath::Frac(Time / PoseSeconds) > 0.45f && FMath::Frac(Time / PoseSeconds) < 0.5f)
439		{
440			UE_LOG(LogJamGame, Display, TEXT("Gallery pose %d: %s"), GalleryPose, *HeroView->DescribeHand());
441		}
442		// The camera stands at the hero's right front, then at his left front for the second half of each pose.
443		const FVector Body = HeroView->GetActorLocation() + FVector(0.0, 0.0, 110.0);
444		const bool bRightSide = FMath::Frac(Time / PoseSeconds) < 0.5f;
445		const FVector Forward = HeroView->GetActorForwardVector();
446		const FVector Side = HeroView->GetActorRightVector() * (bRightSide ? 1.0 : -1.0);
447		Rig->Frame(Body + Forward * 220.0 + Side * 160.0 + FVector(0.0, 0.0, 60.0), Body, 45.f);
448	}
