	DrawText(JamTexts::HeroHealth(FMath::CeilToInt32(Hero.Health)), FLinearColor::White, HudMargin * W, HeroTextY, Font, HudTextScale);
	DrawLoadout(Fight.Ledger, Hero.Ultimate.Meter, HudMargin * W, HeroTextY - 6.f);

