#include "Audio/JamVoiceRules.h"
#include "CoreMinimal.h"
#include "GameFramework/Actor.h"

#include "JamVoice.generated.h"

class UAudioComponent;
class USoundWave;

/**
 * The voice-over: says the lines JamVoiceRules picks one after another, never two at once, and the Publisher's barks
 * now and then in the fight. Runs on real time, so a slowed world does not stretch a line. A line outlives the steal
 * card it started on.
 *
 * The sounds are /Game/Audio/Voice/<line name>; a missing one is skipped silently with its subtitle.
 */
UCLASS()
class JAMGAME_API AJamVoice : public AActor
{
	GENERATED_BODY()

public:
	AJamVoice();

	virtual void Tick(float DeltaSeconds) override;

	/** Queues Line, or says it at once over everything when it cuts in (JamVoiceRules::CutsIn) or bNow. */
	void Say(EJamLine Line, bool bNow = false);

	/** The lines of a frame's events, and the barks of the fight; Fight is the state after the events. */
	void Hear(const TArray<FJamEvent>& Events, const FJamFight& Fight);

	/** Stops the line being said and drops the queue. */
	void Hush();

	/** The line being said now, false when nobody talks. */
	bool Current(EJamLine& OutLine) const;

private:
	void StartNext(float Now);

	UPROPERTY()
	TArray<TObjectPtr<USoundWave>> Sounds;

	UPROPERTY()
	TObjectPtr<UAudioComponent> Playing;

	TArray<EJamLine> Queue;
	bool bSpeaking = false;
	EJamLine Line = EJamLine::IntroBoss;
	/** Real time the line being said ends, and the next bark is due (negative: not yet set). */
	float LineEnd = 0.f;
	float NextBark = -1.f;
	EJamLine LastBark = EJamLine::Bark4;
	FRandomStream Stream;
};

